            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/schedules/{id}": {
          "get": {
            "summary": "Fetch a created schedule",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
